<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            if (current.length > 0) {
                const actualValue = current[0];
                if (typeof actualValue === 'boolean') {
                    return actualValue;
                }
                return String(actualValue);
            } else {
                return defaultValue;
            }
        }
        if (typeof current === 'boolean') {
            return current;
        }
        return String(current);
    }

    function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);
        if (!valueMainDisplay) return;
        let fullDisplayString = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
        let numericValue = min;
        let descriptionText = "";
        const descriptionMatch = String(fullDisplayString).match(/\((.+)\)$/);
        if (descriptionMatch && descriptionMatch[1]) {
            descriptionText = descriptionMatch[1];
            fullDisplayString = String(fullDisplayString).substring(0, descriptionMatch.index).trim();
        }
        const valueMatch = String(fullDisplayString).match(/(-?\d+(\.\d+)?)(?=[^\d.]*$|->)/);
        if (valueMatch) {
            numericValue = parseFloat(valueMatch[1]);
            const parts = String(fullDisplayString).split('->');
            valueMainDisplay.innerText = parts.length > 1 ? parts[1].trim() : parts[0].trim();
        } else if (!isNaN(parseFloat(fullDisplayString))) {
            numericValue = parseFloat(fullDisplayString);
            valueMainDisplay.innerText = fullDisplayString;
        } else {
            if (Array.isArray(rawValueFromCharacterData) && typeof rawValueFromCharacterData[0] === 'number') {
                numericValue = rawValueFromCharacterData[0];
                valueMainDisplay.innerText = String(numericValue);
            } else if (typeof rawValueFromCharacterData === 'number' || typeof rawValueFromCharacterData === 'string') {
                valueMainDisplay.innerText = String(rawValueFromCharacterData);
            } else {
                valueMainDisplay.innerText = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
            }
        }
        if (valueDescDisplay) {
            valueDescDisplay.innerText = descriptionText ? `(${descriptionText})` : "";
        }
        if (progressBar) {
            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            progressBar.style.backgroundColor = color ? color : 'var(--accent-highlight)';
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
        arrow.innerText = isExpanded ? '▲' : '▼';
    }

    function setValue(elementId, value, fallback = '') {
        const element = document.getElementById(elementId);
        if (!element) return;
        if (value === undefined || value === null || value === 'N/A') {
            element.innerText = fallback;
            return;
        }
        if (typeof value === 'string') {
            const trimmed = value.trim();
            element.innerText = trimmed.length === 0 ? fallback : trimmed;
            return;
        }
        element.innerText = value;
    }

    function getNestedValue(obj, path) {
        if (!obj) return undefined;
        const keys = path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null) return undefined;
            current = current[keys[i]];
        }
        return current;
    }

    function renderSceneInfo(data) {
        const container = document.getElementById('scene-info');
        if (!container) return;
        container.innerHTML = '';
        const sceneInfo = getNestedValue(data, '世界.场景信息');
        if (sceneInfo === undefined || sceneInfo === null || (Array.isArray(sceneInfo) && sceneInfo.length === 0)) {
            setValue('scene-overview', '暂无场景记录', '暂无场景记录');
            setValue('scene-overview-desc', '待剧情触发后刷新', '待剧情触发后刷新');
            return;
        }
        let recordCount = 0;
        let primarySummary = '';
        const createEntry = (title, lines) => {
            const entry = document.createElement('div');
            entry.className = 'scene-entry';
            if (title && title.length > 0) {
                const titleBlock = document.createElement('div');
                titleBlock.className = 'scene-entry-title';
                titleBlock.innerText = title;
                entry.appendChild(titleBlock);
            }
            const body = document.createElement('div');
            body.className = 'scene-entry-body';
            const validLines = Array.isArray(lines) && lines.length > 0 ? lines : [['描述', '未记录']];
            validLines.forEach(([label, value]) => {
                const line = document.createElement('div');
                line.className = 'scene-entry-line';
                const tag = document.createElement('span');
                tag.className = 'scene-tag';
                tag.innerText = label;
                const content = document.createElement('span');
                content.className = 'scene-text';
                content.innerText = value;
                line.appendChild(tag);
                line.appendChild(content);
                body.appendChild(line);
            });
            entry.appendChild(body);
            container.appendChild(entry);
            if (!primarySummary) {
                if (title && validLines.length > 0) {
                    primarySummary = `${title} · ${validLines[0][1]}`;
                } else if (title) {
                    primarySummary = title;
                } else {
                    primarySummary = validLines[0][1];
                }
            }
        };
        const appendDetail = (name, detail) => {
            recordCount += 1;
            if (detail && typeof detail === 'object' && !Array.isArray(detail)) {
                const lines = [];
                if (detail.hasOwnProperty('当前服饰')) {
                    lines.push(['服饰', detail.当前服饰 || '未记录']);
                }
                if (detail.hasOwnProperty('当前姿势')) {
                    lines.push(['姿势', detail.当前姿势 || '未记录']);
                }
                if (detail.hasOwnProperty('当前想法')) {
                    lines.push(['心念', detail.当前想法 || '未记录']);
                }
                Object.keys(detail).forEach((key) => {
                    if (key === '当前服饰' || key === '当前姿势' || key === '当前想法') return;
                    lines.push([key, detail[key] || '未记录']);
                });
                createEntry(name, lines);
                return;
            }
            const text = detail === undefined || detail === null ? '未记录' : String(detail);
            createEntry(name, [['描述', text]]);
        };
        if (Array.isArray(sceneInfo)) {
            sceneInfo.forEach((item) => {
                if (item && typeof item === 'object' && !Array.isArray(item)) {
                    Object.keys(item).forEach((name) => {
                        appendDetail(name, item[name]);
                    });
                } else if (item !== undefined && item !== null) {
                    appendDetail(`片段${recordCount + 1}`, item);
                }
            });
        } else if (sceneInfo && typeof sceneInfo === 'object') {
            Object.keys(sceneInfo).forEach((name) => {
                appendDetail(name, sceneInfo[name]);
            });
        } else {
            appendDetail('场景', sceneInfo);
        }
        if (recordCount === 0) {
            setValue('scene-overview', '暂无场景记录', '暂无场景记录');
            setValue('scene-overview-desc', '待剧情触发后刷新', '待剧情触发后刷新');
            return;
        }
        const summaryText = primarySummary || `记录${recordCount}条场景讯息`;
        setValue('scene-overview', summaryText, summaryText);
        const descText = recordCount === 1 ? '记录1条场景讯息' : `记录${recordCount}条场景讯息`;
        setValue('scene-overview-desc', descText, descText);
    }

    function assignCharacter(data, path, prefix, min, max, color) {
        const target = getNestedValue(data, path);
        const affectionRaw = target && target.hasOwnProperty('好感度') ? target.好感度 : min;
        updateProgressBar(`${prefix}-affection-bar`, `${prefix}-affection`, `${prefix}-affection-desc`, affectionRaw !== undefined ? affectionRaw : min, min, max, color);
        let affectionDesc = '';
        if (Array.isArray(affectionRaw) && affectionRaw.length > 1) {
            affectionDesc = affectionRaw[1];
        }
        setValue(`${prefix}-affection-desc`, affectionDesc, `${min}至${max}`);
        const realmRaw = target ? target.境界 : undefined;
        const realmMain = Array.isArray(realmRaw) ? realmRaw[0] : realmRaw;
        const realmDesc = Array.isArray(realmRaw) && realmRaw.length > 1 ? realmRaw[1] : '';
        setValue(`${prefix}-realm`, realmMain || '未入道', '未入道');
        setValue(`${prefix}-realm-desc`, realmDesc || '', '');
        const memoryRaw = target ? target.事件记忆 : undefined;
        let memoryMain = memoryRaw;
        let memoryDesc = '';
        if (Array.isArray(memoryRaw)) {
            memoryMain = memoryRaw[0];
            memoryDesc = memoryRaw.length > 1 ? memoryRaw[1] : '';
        }
        setValue(`${prefix}-memory`, memoryMain || '暂无记录', '暂无记录');
        setValue(`${prefix}-memory-desc`, memoryDesc || '', '');
    }

