            if (detail && typeof detail === 'object' && !Array.isArray(detail)) {
                const lines = [];
                if (detail.hasOwnProperty('当前服饰')) {
                    lines.push(['服饰', detail.当前服饰 || '未记录']);
                }
                if (detail.hasOwnProperty('当前姿势')) {
                    lines.push(['姿势', detail.当前姿势 || '未记录']);
                }
                if (detail.hasOwnProperty('当前想法')) {
                    lines.push(['心念', detail.当前想法 || '未记录']);
                }
                Object.keys(detail).forEach((key) => {
                    if (key === '当前服饰' || key === '当前姿势' || key === '当前想法') return;
                    lines.push([key, detail[key] || '未记录']);
                });
                createEntry(name, lines);
                return;
            }
            const text = detail === undefined || detail === null ? '未记录' : String(detail);
            createEntry(name, [['描述', text]]);
        };
        if (Array.isArray(sceneInfo)) {
            sceneInfo.forEach((item) => {
                if (item && typeof item === 'object' && !Array.isArray(item)) {
                    Object.keys(item).forEach((name) => {
                        appendDetail(name, item[name]);
                    });
                } else if (item !== undefined && item !== null) {
                    appendDetail(`片段${recordCount + 1}`, item);
                }
            });
        } else if (sceneInfo && typeof sceneInfo === 'object') {
            Object.keys(sceneInfo).forEach((name) => {
                appendDetail(name, sceneInfo[name]);
            });
        } else {
            appendDetail('场景', sceneInfo);
        }
        if (recordCount === 0) {
            setValue('scene-overview', '暂无场景记录', '暂无场景记录');
            setValue('scene-overview-desc', '待剧情触发后刷新', '待剧情触发后刷新');
            return;
        }
        const summaryText = primarySummary || `记录${recordCount}条场景讯息`;
        setValue('scene-overview', summaryText, summaryText);
        const descText = recordCount === 1 ? '记录1条场景讯息' : `记录${recordCount}条场景讯息`;
        setValue('scene-overview-desc', descText, descText);
    }

    function assignCharacter(data, path, prefix, min, max, color) {
        const target = getNestedValue(data, path);
        const affectionRaw = target && target.hasOwnProperty('好感度') ? target.好感度 : min;
        updateProgressBar(`${prefix}-affection-bar`, `${prefix}-affection`, `${prefix}-affection-desc`, affectionRaw !== undefined ? affectionRaw : min, min, max, color);
        let affectionDesc = '';
        if (Array.isArray(affectionRaw) && affectionRaw.length > 1) {
            affectionDesc = affectionRaw[1];
        }
        setValue(`${prefix}-affection-desc`, affectionDesc, `${min}至${max}`);
        const realmRaw = target ? target.境界 : undefined;
        const realmMain = Array.isArray(realmRaw) ? realmRaw[0] : realmRaw;
        const realmDesc = Array.isArray(realmRaw) && realmRaw.length > 1 ? realmRaw[1] : '';
        setValue(`${prefix}-realm`, realmMain || '未入道', '未入道');
        setValue(`${prefix}-realm-desc`, realmDesc || '', '');
        const memoryRaw = target ? target.事件记忆 : undefined;
        let memoryMain = memoryRaw;
        let memoryDesc = '';
        if (Array.isArray(memoryRaw)) {
            memoryMain = memoryRaw[0];
            memoryDesc = memoryRaw.length > 1 ? memoryRaw[1] : '';
        }
        setValue(`${prefix}-memory`, memoryMain || '暂无记录', '暂无记录');
        setValue(`${prefix}-memory-desc`, memoryDesc || '', '');
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (messages empty)</p>";
                return;
            }
            const gameData = messages?.[0]?.data;
            const characterData = gameData?.display_data || gameData?.stat_data;
            if (!characterData) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (characterData missing)</p>";
                return;
            }
            const worldTimeRaw = getNestedValue(characterData, '世界.时间');
            const worldTimeMain = Array.isArray(worldTimeRaw) ? worldTimeRaw[0] : worldTimeRaw;
            const worldTimeExtra = Array.isArray(worldTimeRaw) && worldTimeRaw.length > 1 ? worldTimeRaw[1] : '';
            setValue('world-time', worldTimeMain || '未知时辰', '未知时辰');
            setValue('world-time-desc', worldTimeExtra || '', '');
            const worldLocationRaw = getNestedValue(characterData, '世界.地点');
            const worldLocationMain = Array.isArray(worldLocationRaw) ? worldLocationRaw[0] : worldLocationRaw;
            const worldLocationExtra = Array.isArray(worldLocationRaw) && worldLocationRaw.length > 1 ? worldLocationRaw[1] : '';
            setValue('world-location', worldLocationMain || '未知地点', '未知地点');
            setValue('world-location-desc', worldLocationExtra || '', '');
            renderSceneInfo(characterData);
            const protagonistKey = '{{user}}';
            const protagonistRealm = getNestedValue(characterData, `${protagonistKey}.境界`);
            const protagonistRealmMain = Array.isArray(protagonistRealm) ? protagonistRealm[0] : protagonistRealm;
            const protagonistRealmDesc = Array.isArray(protagonistRealm) && protagonistRealm.length > 1 ? protagonistRealm[1] : '';
            setValue('protagonist-realm', protagonistRealmMain || '凡人', '凡人');
            setValue('protagonist-realm-desc', protagonistRealmDesc || '', '');
            const protagonistTechnique = getNestedValue(characterData, `${protagonistKey}.功法`);
            const protagonistTechniqueMain = Array.isArray(protagonistTechnique) ? protagonistTechnique[0] : protagonistTechnique;
            const protagonistTechniqueDesc = Array.isArray(protagonistTechnique) && protagonistTechnique.length > 1 ? protagonistTechnique[1] : '';
            setValue('protagonist-technique', protagonistTechniqueMain || '无', '无');
            setValue('protagonist-technique-desc', protagonistTechniqueDesc || '', '');
            const protagonistArtifact = getNestedValue(characterData, `${protagonistKey}.法宝`);
            const protagonistArtifactMain = Array.isArray(protagonistArtifact) ? protagonistArtifact[0] : protagonistArtifact;
            const protagonistArtifactDesc = Array.isArray(protagonistArtifact) && protagonistArtifact.length > 1 ? protagonistArtifact[1] : '';
            setValue('protagonist-artifact', protagonistArtifactMain || '无', '无');
            setValue('protagonist-artifact-desc', protagonistArtifactDesc || '', '');
            assignCharacter(characterData, '药王谷.花解语', 'hua', -100, 100, 'var(--accent-herb)');
            assignCharacter(characterData, '合欢宗.凰曦月', 'huangxi', -100, 100, 'var(--accent-amber)');
            assignCharacter(characterData, '合欢宗.凰语心', 'huangyu', -100, 100, 'var(--accent-flame)');
            assignCharacter(characterData, '星河剑宗.凌霜华', 'ling', -100, 100, 'var(--accent-moon)');
            assignCharacter(characterData, '琉璃谷.琉璃仙子', 'liuli', -100, 100, 'var(--accent-lotus)');
        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
</body>
</html>
